function About() {
  return (
    <section id="about" className="about-me">
      <div className="container">
        <h2>About Me</h2>
        <p>Write a compelling paragraph or two about yourself, your passion for your work, and what drives you.</p>
        <p>Highlight your key strengths and what you bring to a team or project.</p>
        {/* Add more details about your journey, philosophy, etc. */}
      </div>
    </section>
  );
}

export default About;
